<template>
  <form :id="formId" class="flex flex-col gap-6" @submit="onFormSubmit">
    <FormItemWrapper label="Date of Birth" name="date_of_birth" :is-required="true">
      <template #default="{ slots }">
        <DatePicker
          id="date_of_birth"
          class="w-full"
          button-class="!sm:max-w-full"
          is-year-month-calendar
          v-bind="slots.componentField"
          :min-value="new CalendarDate(1900, 1, 1)"
          :max-value="today(getLocalTimeZone())"
        />
      </template>
    </FormItemWrapper>

    <FormItemWrapper label="Address" name="address" :is-required="true">
      <template #default="{ slots }">
        <Input id="address" type="input" v-bind="slots.componentField" />
      </template>
    </FormItemWrapper>

    <div class="grid grid-cols-1 sm:grid-cols-3 gap-6 sm:gap-4">
      <FormItemWrapper label="City" name="city" :is-required="true">
        <template #default="{ slots }">
          <Input id="city" type="input" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
      <FormItemWrapper label="State" name="state" :is-required="true">
        <template #default="{ slots }">
          <Select class="border-border" v-bind="slots.componentField">
            <SelectTrigger id="state" class="gap-2">
              <SelectValue
                :class="cn('text-foreground', !slots.componentField.modelValue && 'text-muted-foreground')"
                placeholder="Select an option"
              />
            </SelectTrigger>
            <SelectContent id="state">
              <SelectItem v-for="(item, index) in states" :key="index" :value="item.value">
                {{ item.name ?? item.value }}
              </SelectItem>
            </SelectContent>
          </Select>
        </template>
      </FormItemWrapper>
      <FormItemWrapper label="Zip" name="zip_code" :is-required="true">
        <template #default="{ slots }">
          <Input id="zip_code" v-maska data-maska="#####" type="input" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
    </div>

    <FormItemWrapper label="Military Service" name="military_service" :is-required="true">
      <template #default="{ slots }">
        <Select class="border-border" v-bind="slots.componentField">
          <SelectTrigger id="military_service" class="gap-2">
            <SelectValue
              :class="cn('text-foreground', !slots.componentField.modelValue && 'text-muted-foreground')"
              placeholder="Select an option"
            />
          </SelectTrigger>
          <SelectContent id="military_service">
            <SelectItem v-for="(item, index) in militaryServiceOptions" :key="index" :value="item.value">
              {{ item.name ?? item.value }}
            </SelectItem>
          </SelectContent>
        </Select>
      </template>
    </FormItemWrapper>

    <Card class="flex flex-col gap-6 bg-accent p-6">
      <p v-if="variant === 'create'" class="text-sm text-accent-foreground">
        In order to work on a project with Patriot Grassroots you need to be able to have access to a smartphone with
        data and the ability to drive. Please check the box if you can meet those requirements.
      </p>
      <FormItemWrapper name="equipment_confirmation" type="checkbox" :unchecked-value="false" :checked-value="true">
        <template #default="{ slots }">
          <div class="flex !flex-row items-center gap-2">
            <Checkbox id="equipment_confirmation" :model-value="slots.value" v-bind="slots.componentField" />
            <Label for="equipment_confirmation">{{ equipmentLabel }}</Label>
          </div>
        </template>
      </FormItemWrapper>
    </Card>

    <!-- Radio + optional "Other" detail. On edit, a stored value that isn't a preset
         option is prefilled as "Other" (see initialValues) and folded back on submit. -->
    <Card class="flex flex-col gap-6 bg-accent p-6">
      <div class="text-sm text-accent-foreground">
        <p class="font-bold">How did you hear about us?</p>
        <p>Your cooperation is greatly appreciated!</p>
      </div>
      <FormItemWrapper name="referral_source">
        <template #default="{ slots }">
          <RadioGroup
            id="referral_source"
            :default-value="null"
            v-bind="slots.componentField"
            class="flex flex-col gap-6"
          >
            <div v-for="(item, index) in referralSources" :key="item" class="flex items-center gap-2">
              <FormItem class="flex items-center space-y-0 gap-x-3">
                <FormControl>
                  <RadioGroupItem :id="`${item}_${index}`" :value="item" />
                  <Label :for="`${item}_${index}`">{{ item }}</Label>
                </FormControl>
              </FormItem>
            </div>
          </RadioGroup>
        </template>
      </FormItemWrapper>
      <FormItemWrapper v-if="values.referral_source === 'Other'" name="referral_source_other">
        <template #default="{ slots }">
          <Input id="referral_source_other" type="input" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
    </Card>

    <div class="flex justify-end gap-2">
      <Button
        :type="'submit'"
        :form="formId"
        class="w-full sm:w-auto h-10"
        :loading="isSaving"
        :disabled="isUnchanged"
        >{{ submitLabel }}</Button
      >
    </div>

    <NavigationGuard
      v-if="guardUnsavedChanges"
      :saved-data="guardSavedData"
      :changed-data="guardChangedData"
      title="Warning"
      description="You have unsaved changes. Save them before leaving this page."
      confirm-text="Discard Changes"
    />
  </form>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { cloneDeep, isEqual } from 'lodash';
import { cn } from '@/lib/utils';
import { CalendarDate, getLocalTimeZone, today, parseDate } from '@internationalized/date';
import { militaryServiceOptions, states, referralSources } from '~/constants/account';
import {
  getGeneralInfoFormSchema,
  type GeneralInfoFormValues,
  type GeneralInfoVariant,
} from '~/constants/validationSchemas/generalInfoForm';
import type { CanvasserGeneralInfoForm, GeneralInfo } from '~/client';

interface Props {
  variant: GeneralInfoVariant;
  // Prefill (edit). Omitted for create.
  initialData?: GeneralInfo | null;
  submitLabel: string;
  isSaving?: boolean;
  guardUnsavedChanges?: boolean;
  onSubmit: (values: CanvasserGeneralInfoForm) => Promise<void>;
}
const props = withDefaults(defineProps<Props>(), {
  initialData: null,
  isSaving: false,
  guardUnsavedChanges: false,
});

const formId = computed(() => `general-info-${props.variant}-form`);

// On edit the checkbox describes the canvasser being edited, not the admin editing them.
const equipmentLabel = computed(() =>
  props.variant === 'create'
    ? 'I have a smartphone and the ability to drive'
    : 'Has a smartphone and the ability to drive'
);

// Map stored canvasser info onto the form model. The stored free-form referral_source maps
// onto the radio model: a value matching a preset option selects that radio; anything else is
// treated as "Other" with the stored text moved into the detail field (mirrors how submit
// folds "Other" detail back in).
function buildFormValues(data: GeneralInfo | null | undefined) {
  if (!data) return undefined;
  const referralIsPreset = referralSources.includes(data.referral_source);
  return {
    date_of_birth: data.date_of_birth ? parseDate(data.date_of_birth) : undefined,
    address: data.address,
    city: data.city,
    state: data.state,
    zip_code: data.zip_code,
    military_service: data.military_service,
    equipment_confirmation: data.equipment_confirmation,
    referral_source: referralIsPreset ? data.referral_source : 'Other',
    referral_source_other: referralIsPreset ? '' : data.referral_source,
  };
}

// One-time snapshot to seed the form fields (vee-validate reads initialValues once at setup).
const initialValues = buildFormValues(props.initialData);

const { handleSubmit, values } = useForm({
  validationSchema: getGeneralInfoFormSchema(props.variant),
  initialValues,
});

// Data for the edit-variant NavigationGuard. Derive the saved baseline reactively from
// props.initialData (NOT the one-time `initialValues`): saving stays on this page and
// refetches `['user']`, so initialData advances to the just-saved values. A reactive
// baseline advances with it, clearing the guard after a successful save — otherwise the
// saved values keep reading as "unsaved" and the guard fires on GoBack.
// date_of_birth is a @internationalized/date CalendarDate on both sides, and isEqual cannot
// compare two CalendarDate instances reliably (their `calendar` reference differs between
// instances), so an untouched date still reads as "changed". Normalize date_of_birth to its
// ISO string on both sides so the guard compares like-for-like. The live `values` proxy is
// cloned (changedData) before isEqual, which does not compare the live Proxy reliably.
// referral_source_other only carries meaning while "Other" is selected; once a preset is
// chosen its field unmounts and the form value goes stale/undefined, which would otherwise
// read as "changed" forever after switching away from an "Other" value. Normalize it to ''
// on both sides whenever the selection isn't "Other" so the comparison can settle.
const normalizeReferralOther = (referralSource?: string, referralOther?: string) =>
  referralSource === 'Other' ? referralOther : '';
const guardSavedData = computed(() => {
  const saved = buildFormValues(props.initialData);
  return {
    ...saved,
    date_of_birth: saved?.date_of_birth?.toString(),
    referral_source_other: normalizeReferralOther(saved?.referral_source, saved?.referral_source_other),
  };
});
const guardChangedData = computed(() => {
  const snapshot = cloneDeep(values);
  return {
    ...snapshot,
    date_of_birth: (values.date_of_birth as CalendarDate | undefined)?.toString(),
    referral_source_other: normalizeReferralOther(
      values.referral_source as string | undefined,
      values.referral_source_other as string | undefined
    ),
  };
});

// On edit, disable submit until something actually changes. Reuses the same
// normalized saved/changed snapshots as the NavigationGuard so the CalendarDate
// comparison stays reliable (see the guard comment above). Create always allows submit.
const isUnchanged = computed(() => props.variant === 'edit' && isEqual(guardSavedData.value, guardChangedData.value));

const onFormSubmit = handleSubmit(async (formValues) => {
  const { referral_source_other, ...rest } = formValues as GeneralInfoFormValues;
  // Fold the "Other" free text into referral_source before submitting (both variants).
  if (rest.referral_source === 'Other' && referral_source_other) {
    rest.referral_source = referral_source_other;
  }
  try {
    await props.onSubmit(rest as CanvasserGeneralInfoForm);
  } catch {
    // Error toast surfaced by the mutation; keep form state for retry.
  }
});
</script>
