import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import type { MilitaryService } from '~/client';

export type GeneralInfoVariant = 'create' | 'edit';

export interface GeneralInfoFormValues {
  date_of_birth: string;
  address: string;
  city: string;
  state: string;
  zip_code: string;
  military_service: MilitaryService;
  equipment_confirmation: boolean;
  referral_source: string;
  referral_source_other: string;
}

const isNumeric = (value: string): boolean => /^-?\d+$/.test(value);

const textWithAllowedChars = (label: string, max: number) =>
  z
    .string({ message: `${label} is required` })
    .trim()
    .nonempty({ message: `${label} is required` })
    .max(max, { message: `${label} cannot exceed ${max} characters` })
    .regex(/^[A-Za-z0-9\s'.,-]*$/, { message: "Allowed characters are a-z, A-Z, 0-9, ', ., -, space and ," });

export function getGeneralInfoFormSchema(variant: GeneralInfoVariant) {
  return toTypedSchema(
    z
      .object({
        date_of_birth: z.preprocess((val) => val?.toString(), z.string({ message: 'Date of Birth is required' })),
        address: textWithAllowedChars('Address', 1024),
        city: textWithAllowedChars('City', 512),
        state: z.string({ message: 'State is required' }),
        zip_code: z
          .string({ message: 'Zip is required' })
          .refine(isNumeric, { message: 'Zip should be a number' })
          .refine((val) => val.length === 5, { message: 'Zip should be 5 digits' }),
        military_service: z
          .string({ message: 'Military Service is required' })
          .transform((val) => val as MilitaryService),
        equipment_confirmation:
          variant === 'create'
            ? z
                .boolean()
                .default(false)
                .refine((val) => val === true, { message: 'Field is required' })
            : z.boolean().default(false),
        referral_source: z
          .string()
          .default('')
          .refine((val) => val.trim().length > 0, { message: 'Please select how you heard about us' }),
        referral_source_other: z.string().default(''),
      })
      .superRefine((val, ctx) => {
        // When "Other" is selected, the free-text detail is required.
        if (val.referral_source === 'Other' && val.referral_source_other.trim().length === 0) {
          ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['referral_source_other'],
            message: 'Please provide details for the "Other" option',
          });
        }
      })
  );
}
